package com.seaoftales.config;
import com.seaoftales.identity.service.IdentityService; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean UserDetailsService userDetailsService(IdentityService identity){return username->{var u=identity.find(username);return User.withUsername(u.getUsername()).password(u.getPasswordHash()).roles(u.getRole().name()).disabled(!u.isEnabled()).build();};} @Bean SecurityFilterChain securityFilterChain(HttpSecurity http)throws Exception{http.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/api/invitations/validate","/api/identity/options").permitAll().requestMatchers(HttpMethod.GET,"/api/reactions/**").permitAll().requestMatchers("/api/reactions/**").authenticated().requestMatchers("/api/library/**").authenticated().requestMatchers(HttpMethod.PATCH,"/api/profiles/me").authenticated().requestMatchers(HttpMethod.POST,"/api/novels").hasRole("ADMIN").requestMatchers("/api/invitations/**","/api/admin/**").hasRole("ADMIN").requestMatchers("/api/author/**").hasAnyRole("AUTHOR","ADMIN").requestMatchers("/api/editor/**").hasAnyRole("EDITOR","ADMIN").anyRequest().permitAll()).formLogin(f->f.disable()).httpBasic(b->b.disable()).logout(l->l.logoutUrl("/api/auth/logout").logoutSuccessHandler((r,s,a)->s.setStatus(204)));return http.build();} }
